import{_ as a,I as t,g as o,j as s}from"./chunks/framework.CjoWWfVe.js";const m=JSON.parse('{"title":"Features & Roadmap","description":"Current status of OmniCraft ERP and future development roadmap.","frontmatter":{"title":"Features & Roadmap","description":"Current status of OmniCraft ERP and future development roadmap.","order":4},"headers":[],"relativePath":"docs/roadmap.md","filePath":"docs/roadmap.md"}'),n={name:"docs/roadmap.md"};function r(i,e,l,c,u,d){return t(),o("div",null,[...e[0]||(e[0]=[s('<div class="warning custom-block"><p class="custom-block-title">📌 Documentation is under development</p><p><strong>Dear users!</strong></p><p>Since OmniCraft ERP is currently in an active beta stage, being regularly improved and expanded, the reference materials are also updated gradually.</p><p>At the moment, please treat the documentation as indicative — it is incomplete, may temporarily lack descriptions of some features, or contain inaccuracies.</p></div><h1 id="🚀-features-roadmap" tabindex="-1">🚀 Features &amp; Roadmap <a class="header-anchor" href="#🚀-features-roadmap" aria-label="Permalink to &quot;🚀 Features &amp; Roadmap&quot;">​</a></h1><p>OmniCraft ERP is an actively developing product. We regularly release updates based on our own craft practice and user feedback. On this page, you can find out what is already working stably and what features are in development.</p><h2 id="✅-current-status-stable-core-version-1-0-x" tabindex="-1">✅ Current Status: Stable Core (Version 1.0.x) <a class="header-anchor" href="#✅-current-status-stable-core-version-1-0-x" aria-label="Permalink to &quot;✅ Current Status: Stable Core (Version 1.0.x)&quot;">​</a></h2><p>At the moment, the <strong>Main Production Pipeline</strong> is fully implemented and debugged. The basic version of the program allows you to conduct full management accounting of a micro-enterprise:</p><ul><li><strong>Property:</strong> Smart equipment depreciation and calculation of the residual value of the workshop.</li><li><strong>Warehouse (MAC):</strong> Batch accounting of raw materials with the distribution of delivery costs to the cost of materials without distortion.</li><li><strong>Calculator:</strong> Recipe builder taking into account the master&#39;s labor and overhead costs.</li><li><strong>Production:</strong> Dynamic workbench with smart cascading recalculation of raw material reserves (FIFO queue).</li><li><strong>Sales:</strong> Management of sales channels, markups, and a POS terminal taking into account logistics costs (paid by the client or the workshop).</li><li><strong>Finance:</strong> Global management balance (Capital), cash book (Cash Flow), and advanced graphical analytics (Financial Pulse, Break-even point).</li><li><strong>Security:</strong> Built-in rotational GFS backups, WAL database logging mode, and protection against data loss during power outages.</li></ul><p>All these functions are available under the <a href="./licenses">Basic (Standard) license</a>.</p><hr><h2 id="✅-implemented-pro-mode-ecosystem" tabindex="-1">✅ Implemented: PRO Mode &amp; Ecosystem <a class="header-anchor" href="#✅-implemented-pro-mode-ecosystem" aria-label="Permalink to &quot;✅ Implemented: PRO Mode &amp; Ecosystem&quot;">​</a></h2><p>As part of expanding the system&#39;s capabilities to the corporate level (PRO version), the following features have been successfully implemented and are working stably:</p><ul><li><strong>Multi-Workspaces:</strong> Creating independent databases for running several different businesses (for example, a leather workshop and retail trade) with instant switching.</li><li><strong>Global &quot;My Capital&quot; Dashboard:</strong> A revolutionary approach to personal finance accounting. The program consolidates the profits of all your businesses and automatically calculates daily living expenses through the capital delta (without having to enter every receipt).</li><li><strong>Marketplace and Global Modules:</strong> Flexible plugin architecture (Add-ons) with zero impact on computer performance.</li><li><strong>Ambassador Module:</strong> Built-in organic promotion system (Growth Hacking) with auto-generation of UTM links, QR codes on receipts, and an internal bonus store.</li></ul><hr><h2 id="🔮-in-development-custom-modules-extensions-roadmap" tabindex="-1">🔮 In Development: Custom Modules &amp; Extensions (Roadmap) <a class="header-anchor" href="#🔮-in-development-custom-modules-extensions-roadmap" aria-label="Permalink to &quot;🔮 In Development: Custom Modules &amp; Extensions (Roadmap)&quot;">​</a></h2><p>The foundation of the ecosystem is laid. The further development of the project will be focused on creating <strong>specialized global modules</strong>, which will be developed as requests from crafters arise.</p><p>Possible future extensions:</p><ul><li><strong>&quot;Patterns&quot; Module:</strong> Cataloging patterns, calculating leather cutting area, linking PDF/CAD drawings.</li><li><strong>&quot;Services &amp; Custom&quot; Module:</strong> Accounting for individual repairs and custom tailoring with an assessment of the time spent without a classic product showcase.</li><li><strong>&quot;Marketing &amp; ROI&quot; Module:</strong> Accounting for the master&#39;s advertising budgets with automatic calculation of the payback of each sales channel.</li></ul><blockquote><p><strong>Individual Custom Development</strong> The marketplace architecture allows us to develop unique closed modules tailored to your individual business processes (for example, specific processes for jewelers, ceramicists, or woodworking shops) upon request from the community.</p></blockquote>',17)])])}const h=a(n,[["render",r]]);export{m as __pageData,h as default};
